import Vue from 'vue';
//配置路由
import VueRouter from 'vue-router'
Vue.use(VueRouter);
//1.创建组件
import Index from '@/views/index'
import Home from '@/views/home'
import Login from '@/views/login'
import NotFound from '@/views/404'
import UpdatePassword from '@/views/update-password'
import pay from '@/views/pay'
import register from '@/views/register'
import center from '@/views/center'

     import users from '@/views/modules/users/list'
    import dictionary from '@/views/modules/dictionary/list'
    import gongyinghsang from '@/views/modules/gongyinghsang/list'
    import goods from '@/views/modules/goods/list'
    import goodsChuruInout from '@/views/modules/goodsChuruInout/list'
    import goodsChuruInoutList from '@/views/modules/goodsChuruInoutList/list'
    import goodsOrder from '@/views/modules/goodsOrder/list'
    import kehu from '@/views/modules/kehu/list'
    import news from '@/views/modules/news/list'
    import yonghu from '@/views/modules/yonghu/list'
    import dictionaryCangku from '@/views/modules/dictionaryCangku/list'
    import dictionaryGongyinghsang from '@/views/modules/dictionaryGongyinghsang/list'
    import dictionaryGongyinghsangXinyong from '@/views/modules/dictionaryGongyinghsangXinyong/list'
    import dictionaryGoods from '@/views/modules/dictionaryGoods/list'
    import dictionaryGoodsChuruInout from '@/views/modules/dictionaryGoodsChuruInout/list'
    import dictionaryGoodsOrder from '@/views/modules/dictionaryGoodsOrder/list'
    import dictionaryNews from '@/views/modules/dictionaryNews/list'
    import dictionarySex from '@/views/modules/dictionarySex/list'





//2.配置路由   注意：名字
const routes = [{
    path: '/index',
    name: '首页',
    component: Index,
    children: [{
      // 这里不设置值，是把main作为默认页面
      path: '/',
      name: '首页',
      component: Home,
      meta: {icon:'', title:'center'}
    }, {
      path: '/updatePassword',
      name: '修改密码',
      component: UpdatePassword,
      meta: {icon:'', title:'updatePassword'}
    }, {
      path: '/pay',
      name: '支付',
      component: pay,
      meta: {icon:'', title:'pay'}
    }, {
      path: '/center',
      name: '个人信息',
      component: center,
      meta: {icon:'', title:'center'}
    } ,{
        path: '/users',
        name: '管理信息',
        component: users
      }
    ,{
        path: '/dictionaryCangku',
        name: '仓库',
        component: dictionaryCangku
    }
    ,{
        path: '/dictionaryGongyinghsang',
        name: '供应商类型',
        component: dictionaryGongyinghsang
    }
    ,{
        path: '/dictionaryGongyinghsangXinyong',
        name: '供应商信用等级名称',
        component: dictionaryGongyinghsangXinyong
    }
    ,{
        path: '/dictionaryGoods',
        name: '商品类型',
        component: dictionaryGoods
    }
    ,{
        path: '/dictionaryGoodsChuruInout',
        name: '采购入库类型',
        component: dictionaryGoodsChuruInout
    }
    ,{
        path: '/dictionaryGoodsOrder',
        name: '预定状态',
        component: dictionaryGoodsOrder
    }
    ,{
        path: '/dictionaryNews',
        name: '公告类型',
        component: dictionaryNews
    }
    ,{
        path: '/dictionarySex',
        name: '性别',
        component: dictionarySex
    }


    ,{
        path: '/dictionary',
        name: '字典表',
        component: dictionary
      }
    ,{
        path: '/gongyinghsang',
        name: '供应商',
        component: gongyinghsang
      }
    ,{
        path: '/goods',
        name: '商品',
        component: goods
      }
    ,{
        path: '/goodsChuruInout',
        name: '采购入库',
        component: goodsChuruInout
      }
    ,{
        path: '/goodsChuruInoutList',
        name: '采购入库详情',
        component: goodsChuruInoutList
      }
    ,{
        path: '/goodsOrder',
        name: '商品预定',
        component: goodsOrder
      }
    ,{
        path: '/kehu',
        name: '客户',
        component: kehu
      }
    ,{
        path: '/news',
        name: '公告信息',
        component: news
      }
    ,{
        path: '/yonghu',
        name: '员工',
        component: yonghu
      }


    ]
  },
  {
    path: '/login',
    name: 'login',
    component: Login,
    meta: {icon:'', title:'login'}
  },
  {
    path: '/register',
    name: 'register',
    component: register,
    meta: {icon:'', title:'register'}
  },
  {
    path: '/',
    name: '首页',
    redirect: '/index'
  }, /*默认跳转路由*/
  {
    path: '*',
    component: NotFound
  }
]
//3.实例化VueRouter  注意：名字
const router = new VueRouter({
  mode: 'hash',
  /*hash模式改为history*/
  routes // （缩写）相当于 routes: routes
})

export default router;
